import java.util.concurrent.Semaphore;
import java.util.function.IntConsumer;

class ZeroEvenOdd {
  private final int n;
  private final Semaphore zeroSem = new Semaphore(1); // zero starts
  private final Semaphore oddSem = new Semaphore(0);
  private final Semaphore evenSem = new Semaphore(0);

  public ZeroEvenOdd(int n) {
    this.n = n;
  }

  // zero runs n times: print 0, then wake exactly one number thread.
  public void zero(IntConsumer printNumber) throws InterruptedException {
    for (int i = 1; i <= n; i++) {
      zeroSem.acquire();
      printNumber.accept(0);
      if ((i & 1) == 1) oddSem.release();
      else evenSem.release();
    }
  }

  public void even(IntConsumer printNumber) throws InterruptedException {
    for (int i = 2; i <= n; i += 2) {
      evenSem.acquire();
      printNumber.accept(i);
      zeroSem.release();
    }
  }

  public void odd(IntConsumer printNumber) throws InterruptedException {
    for (int i = 1; i <= n; i += 2) {
      oddSem.acquire();
      printNumber.accept(i);
      zeroSem.release();
    }
  }
}

import threading

class ZeroEvenOdd:
    def __init__(self, n: int):
        self.n = n
        self.zero_sem = threading.Semaphore(1)
        self.odd_sem = threading.Semaphore(0)
        self.even_sem = threading.Semaphore(0)

    def zero(self, printNumber):
        for i in range(1, self.n + 1):
            self.zero_sem.acquire()
            printNumber(0)
            if i % 2 == 1:
                self.odd_sem.release()
            else:
                self.even_sem.release()

    def even(self, printNumber):
        for i in range(2, self.n + 1, 2):
            self.even_sem.acquire()
            printNumber(i)
            self.zero_sem.release()

    def odd(self, printNumber):
        for i in range(1, self.n + 1, 2):
            self.odd_sem.acquire()
            printNumber(i)
            self.zero_sem.release()

import java.util.concurrent.locks.*;
import java.util.function.IntConsumer;

class ZeroEvenOddLock {
  private final int n;
  private int cur = 1;
  private boolean zeroTurn = true; // predicate guarded by lock
  private final ReentrantLock lock = new ReentrantLock();
  private final Condition cond = lock.newCondition();

  ZeroEvenOddLock(int n) { this.n = n; }

  public void zero(IntConsumer out) throws InterruptedException {
    for (int i = 1; i <= n; i++) {
      lock.lock();
      try {
        while (!zeroTurn) cond.await(); // while, not if: spurious wakeups
        out.accept(0);
        zeroTurn = false;
        cond.signalAll(); // wake the one parity owner; broadcast is simpler
      } finally { lock.unlock(); }
    }
  }

  public void even(IntConsumer out) throws InterruptedException {
    for (int i = 2; i <= n; i += 2) {
      lock.lock();
      try {
        while (zeroTurn || (cur & 1) == 1) cond.await();
        out.accept(i);
        cur++; zeroTurn = true;
        cond.signalAll();
      } finally { lock.unlock(); }
    }
  }

  public void odd(IntConsumer out) throws InterruptedException {
    for (int i = 1; i <= n; i += 2) {
      lock.lock();
      try {
        while (zeroTurn || (cur & 1) == 0) cond.await();
        out.accept(i);
        cur++; zeroTurn = true;
        cond.signalAll();
      } finally { lock.unlock(); }
    }
  }
}
